static int sgn(ll x) {
    if (x < 0) return -1;
    if (x > 0) return 1;
    return 0;
}

static ll cross(ll ax, ll ay, ll bx, ll by, ll cx, ll cy) {
    return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
}

static int between(ll a, ll b, ll x) {
    if (a > b) { ll t = a; a = b; b = t; }
    return a <= x && x <= b;
}

/* Returns:
   0 -> no intersection
   1 -> proper / point intersection
   2 -> collinear overlap (infinitely many points)
*/
static int segment_intersection_type(Seg a, Seg b) {
    ll c1 = cross(a.x1, a.y1, a.x2, a.y2, b.x1, b.y1);
    ll c2 = cross(a.x1, a.y1, a.x2, a.y2, b.x2, b.y2);
    ll c3 = cross(b.x1, b.y1, b.x2, b.y2, a.x1, a.y1);
    ll c4 = cross(b.x1, b.y1, b.x2, b.y2, a.x2, a.y2);

    int s1 = sgn(c1), s2 = sgn(c2), s3 = sgn(c3), s4 = sgn(c4);

    if (s1 == 0 && s2 == 0 && s3 == 0 && s4 == 0) {
        int overlap =
            !( (a.x1 < a.x2 ? a.x2 : a.x1) < (b.x1 < b.x2 ? b.x1 : b.x2) ||
               (b.x1 < b.x2 ? b.x2 : b.x1) < (a.x1 < a.x2 ? a.x1 : a.x2) ||
               (a.y1 < a.y2 ? a.y2 : a.y1) < (b.y1 < b.y2 ? b.y1 : b.y2) ||
               (b.y1 < b.y2 ? b.y2 : b.y1) < (a.y1 < a.y2 ? a.y1 : a.y2));
        return overlap ? 2 : 0;
    }

    if (s1 == 0 && between(a.x1, a.x2, b.x1) && between(a.y1, a.y2, b.y1)) return 1;
    if (s2 == 0 && between(a.x1, a.x2, b.x2) && between(a.y1, a.y2, b.y2)) return 1;
    if (s3 == 0 && between(b.x1, b.x2, a.x1) && between(b.y1, b.y2, a.y1)) return 1;
    if (s4 == 0 && between(b.x1, b.x2, a.x2) && between(b.y1, b.y2, a.y2)) return 1;

    if (s1 * s2 < 0 && s3 * s4 < 0) return 1;
    return 0;
}

