struct Pt {
    long double x, y;
};

long double cross(const Pt& a, const Pt& b, const Pt& c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

bool onSeg(const Pt& a, const Pt& b, const Pt& p) {
    const long double EPS = 1e-12L;
    return fabsl(cross(a,b,p)) <= EPS &&
           min(a.x,b.x)-EPS <= p.x && p.x <= max(a.x,b.x)+EPS &&
           min(a.y,b.y)-EPS <= p.y && p.y <= max(a.y,b.y)+EPS;
}

int sgn(long double v) {
    const long double EPS = 1e-12L;
    if (v > EPS) return 1;
    if (v < -EPS) return -1;
    return 0;
}

bool properIntersect(const Pt& a, const Pt& b, const Pt& c, const Pt& d) {
    long double c1 = cross(a,b,c), c2 = cross(a,b,d);
    long double c3 = cross(c,d,a), c4 = cross(c,d,b);
    int s1 = sgn(c1), s2 = sgn(c2), s3 = sgn(c3), s4 = sgn(c4);

    if (s1 == 0 && onSeg(a,b,c)) return true;
    if (s2 == 0 && onSeg(a,b,d)) return true;
    if (s3 == 0 && onSeg(c,d,a)) return true;
    if (s4 == 0 && onSeg(c,d,b)) return true;

    return (s1 * s2 < 0) && (s3 * s4 < 0);
}

bool lineIntersection(const Pt& a, const Pt& b, const Pt& c, const Pt& d, Pt& out) {
    long double A1 = b.y - a.y;
    long double B1 = a.x - b.x;
    long double C1 = A1 * a.x + B1 * a.y;

    long double A2 = d.y - c.y;
    long double B2 = c.x - d.x;
    long double C2 = A2 * c.x + B2 * c.y;

    long double det = A1 * B2 - A2 * B1;
    const long double EPS = 1e-12L;
    if (fabsl(det) <= EPS) return false;

    out.x = (B2 * C1 - B1 * C2) / det;
    out.y = (A1 * C2 - A2 * C1) / det;
    return true;
}

