    vector<pair<long double,int>> ev; // position along AB, company(0 same,1 competitor)

    long double dx = B.x - A.x, dy = B.y - A.y;
    long double len2 = dx*dx + dy*dy;

    for (int i = 0; i < n; ++i) {
        Pt C, D;
        string t;
        cin >> C.x >> C.y >> D.x >> D.y >> t;

        if (!properIntersect(A,B,C,D)) continue;

        Pt P;
        if (!lineIntersection(A,B,C,D,P)) {
            // Collinear overlap or parallel; ambiguous in this abbreviated statement.
            // Ignore degenerate overlaps.
            continue;
        }

        long double param = ((P.x - A.x)*dx + (P.y - A.y)*dy) / len2;
        int company = isSameCompany(t) ? 0 : 1;
        ev.push_back({param, company});
    }

    if (ev.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ev.begin(), ev.end(), [](const auto& p1, const auto& p2){
        if (fabsl(p1.first - p2.first) > 1e-12L) return p1.first < p2.first;
        return p1.second < p2.second;
    });

    int runs = 1;
    for (int i = 1; i < (int)ev.size(); ++i) {
        if (ev[i].second != ev[i-1].second) runs++;
    }

    cout << runs + 1 << '\n';
    return 0;
}
